 add('Props','مدخلات المكوّن','Object بالقيم اللي الأب يمررها للابن في render.','يقرأها Component مباشرة أو عبر destructuring؛ يمكن أن تتضمن نصوصًا وبيانات ودوالًا وعناصر.','الابن لا يعدلها؛ إذا احتاج تغييرًا ينادي callback من صاحب البيانات.',['props','Prop','prop']);
 add('children','المحتوى داخل المكوّن','Prop تجمع ما بين فتح وإغلاق استخدام Component.','الحاوية تحدد مكان العرض، والمستدعي يختار المحتوى. ده جزء من Composition.','مش شرط array دائمًا، ومش مشاركة تلقائية في state داخل العناصر.');
 add('State','حالة المكوّن','ذاكرة تديرها React وتربطها بهوية Component في الشجرة.','setter تطلب القيمة التالية وrender جديد مناسب، والقيمة الحالية لقطة لهذا الحساب.','تغيير متغير محلي مش تحديث state، وتعديل object القديمة يكسر وضوح اللقطات.',['state','الحالة']);
 add('useState','Hook الذاكرة','دالة React ترجع قيمة حالة ودالة تحديثها.','تهيئة مرة لكل هوية، وقراءة القيمة في render، والتحديث بقيمة أو updater نقي.','Setter تستبدل object ولا تدمجها تلقائيًا، ولا تغير متغير اللقطة الحالية فورًا.',['setState','setter','setCount']);
 add('Render','حساب وصف الواجهة','مرحلة تستدعي React فيها Component لحساب عناصرها من props وstate.','تنتج وصفًا جديدًا للشجرة ثم تقرر ما يحتاج تطبيقًا.','يجب أن يبقى الحساب نقيًا، وقد يحدث بدون تغيير مرئي في DOM.',['render','Re-render','re-render','الرندر','رندر']);
 add('Commit','تطبيق تغييرات الواجهة','مرحلة تطبيق التغييرات المطلوبة على DOM بعد حساب React.','تنسيق عناصر وإضافة أو حذف أو تحديث وفق النتيجة اللازمة.','مش اسمًا آخر لكل render، ولا يعني إعادة تحميل الوثيقة.',['commit']);
 add('Snapshot','لقطة حالة','قيم props وstate والمتغيرات والدوال الخاصة بحساب Component في لحظة render.','handler من هذا الحساب تقرأ قيم النطاق نفسه حتى بعد طلب تحديث.','console.log بعد setter قد يقرأ القديمة، وtimeout قد يحتفظ بلقطة أقدم.',['snapshot','لقطة']);
 add('Batching','تجميع تحديثات','تجميع React لتحديثات مناسبة قبل إجراء الحساب لتجنب تكرار غير لازم.','التحديثات المعتمدة على السابق تُحسب عبر updater functions في الطابور.','عدة setters تقرأ نفس count لا تتراكم كأن المتغير تغير فورًا.',['batching']);
 add('Hook','واجهة قدرات React','دالة تسمح للمكوّن باستخدام قدرة مثل حالة أو مزامنة.','useState وuseEffect وuseRef هنا تُستدعى في ترتيب ثابت بالمستوى الأعلى المناسب.','لا تناديها داخل if أو loop أو handler؛ اسم دالة يبدأ use لا يجعل أي سياق صالحًا.',['Hooks','هوك']);
 add('useEffect','Hook المزامنة','تسجيل مزامنة مع نظام خارج حساب الواجهة، مثل مؤقت أو شبكة.','setup تنفذ بعد commit وفق القواعد، وقد ترجع cleanup. الاعتمادات تحدد إعادة المزامنة عند اختلاف قيمها.','لا تستخدمها لحساب نتيجة filter من state أو بدل handler لفعل سببه حدث محدد.',['Effect','Effects','effect']);
 add('Cleanup','تنظيف دورة المزامنة','دالة ترجعها setup Effect لإلغاء ما بدأته هذه الدورة.','تعمل قبل إعادة الإعداد عند تغير الاعتمادات وعند إزالة Component.','لا تلغِ مورد دورة أحدث، ولا تعتبر الإلغاء المتوقع خطأ للمستخدم.',['cleanup','التنظيف']);
 add('StrictMode','فحوص تطوير إضافية','غلاف React يساعد اكتشاف نقص النقاء والتنظيف أثناء التطوير.','قد يعيد حسابات مناسبة أو دورة setup وتنظيف إضافية وفق القواعد. لا يضيف عنصر DOM.','إزالة الفحص لإخفاء التكرار تترك السبب. المطلوب منطق صحيح مع إعادة الحساب والتركيب.');
 add('Key','هوية عنصر قائمة','قيمة ثابتة تميز عنصر React وسط إخواته في نفس القائمة.','تساعد متابعة نفس البيانات بين الإضافة والحذف والترتيب؛ توضع على الجذر الراجع من map.','لا تستخدم random أثناء render أو index لقائمة متغيرة، وkey لا تصل كـprop عادية.',['key']);
 add('Fragment','تجميع بدون عنصر DOM','عنصر React يجمع عدة عناصر في نتيجة واحدة من غير حاوية مرئية إضافية.','الصيغة المختصرة &lt;&gt;...&lt;/&gt; مناسبة للتجميع، والصريحة تسمح بمفتاح عند الحاجة.','Fragment المختصرة لا تحمل key؛ في قائمة استخدم الصيغة المناسبة أو حاوية ذات معنى.');
 add('Immutability','عدم تعديل البيانات السابقة','أسلوب يبني قيمة جديدة بدل تغيير object أو array القديمة.','spread وmap وfilter وسائل شائعة لتحديث state مع إبقاء اللقطة السابقة سليمة.','نسخ الخارج وحده لا يكفي لو عدلت object متداخلة مشتركة.',['Immutable update','Mutation','mutation','التعديل المباشر']);
 add('Controlled input','حقل تديره الحالة','حقل قيمته من state وتغيير المستخدم يحدث state عبر onChange.','الدورة: قيمة معروضة ثم حدث ثم setter ثم render بقيمة تالية.','value بدون تحديث تجعل الكتابة لا تظهر؛ checked للـcheckbox وليست value وحدها.',['controlled','Controlled']);
 add('Derived data','بيانات مشتقة','نتيجة يمكن حسابها من بيانات موجودة بدل تخزين نسخة ثانية لها.','قائمة البحث وعدد المكتمل ومجموع القيم تُحسب أثناء render عندما يكفي ذلك.','state مكررة مع Effect للمزامنة تعرضك لتناقض غير لازم.',['Derived state','derived','القيم المشتقة','مشتقة']);
 add('Lifting State Up','رفع الحالة لأب مشترك','نقل الحالة المشتركة لأقرب أب يحتاج تنسيقها بين عدة أبناء.','الأب يمرر القيم والدوال، والأبناء تعرض أو تبلغ بطلب تغيير.','مش معناه جعل كل متغير عالمي أو نسخ state في كل ابن.',['Lifting state','lifting','state مشتركة']);
 add('useRef','مرجع باقٍ بلا render','Hook ترجع object لها current يحتفظ بهويته بين الحسابات.','تخزن مرجع DOM أو قيمة لا يلزم أن يسبب تغيرها تحديث واجهة.','تغيير current لا يطلب render، فلا تستعمله بدل state لعرض رقم متغير.',['ref']);
 add('Custom Hook','دالة لتجميع منطق Hooks','دالة يبدأ اسمها use وتستخدم Hooks لتنظيم سلوك قابل لإعادة الاستخدام.','يمكن أن ترجع قيمًا ودوالًا وتجمع المزامنة والحالة تحت مسؤولية واضحة.','كل استدعاء له حالة مستقلة؛ مشاركة الكود ليست مشاركة تلقائية للذاكرة.',['Custom Hooks']);
 add('AbortController','تحكم في إلغاء عمليات','واجهة تنشئ signal يمكن لعملية مثل fetch متابعتها.','تمرير signal ثم abort يطلب الإلغاء، ومع حماية دورة تمنع الاستجابات القديمة من الكتابة.','الإلغاء لا يعني أن كل أثر حدث في الخادم اتراجع، وAbortError المتوقع لا يُعرض كفشل عام.',['AbortError']);
 add('Race condition','تعارض ترتيب النتائج','مشكلة عندما تعتمد النتيجة على أي عملية غير متزامنة تصل أولًا أو أخيرًا.','طلب قديم قد يرجع بعد طلب أحدث ويكتب بيانات لا تطابق الاختيار الحالي.','سرعة الشبكة في جهازك لا تنفي المشكلة؛ استخدم تنظيفًا وحماية للنتيجة حسب الدورة.');
 add('OOP','تنظيم حول الكائنات','أسلوب يجمع بيانات وسلوكًا ضمن objects وحدود مسؤولية.','classes وprototypes وسائل من JavaScript لتنظيم النسخ ومشاركة السلوك.','مش شرط كل وظيفة تحتاج class؛ اختار أبسط تنظيم يوضح مسؤولية الكود.');
 add('Method','دالة عضو','دالة تستخدم كعضو في object أو class.','this في الدالة العادية تعتمد على طريقة الاستدعاء، وممكن مشاركة methods عبر prototype.','فصل method عن object قد يفقد سياق this؛ Arrow لها قواعد مختلفة.',['Methods','method']);
 add('Property','خاصية كائن','قيمة مسماة على object أو في علاقة الوصول إليه.','تقرأ بالنقطة أو الأقواس، وقد تكون خاصة بالكائن نفسه أو موجودة عبر prototype.','Property في DOM قد تعكس الحالة الحالية، ومش دائمًا نص Attribute في HTML.',['Properties','property']);
 add('Constructor','دالة تهيئة النسخة','منطق يُستخدم عند إنشاء نسخة باستخدام new وفق نظام الدالة أو الكلاس.','يهيئ خواص النسخة، والمشتق يستعمل super قبل this في constructor عند الحاجة.','Arrow لا تعمل كـconstructor، وclass تُستدعى مع new.',['constructor','new','super']);
 add('Prototype','سلسلة تفويض الكائنات','العلاقة اللي تبحث من خلالها JavaScript عن خواص غير موجودة مباشرة على object.','نسخ class قد تشترك في methods على prototype، ويستمر البحث في السلسلة.','مش نسخًا لكل خواص الأب في كل ابن، وتغيير مشترك قد يؤثر على نسخ كثيرة.',['prototype']);
 add('Encapsulation','تغليف واجهة التعامل','تحديد ما يمكن قراءته أو تغييره من خارج الكود المسؤول.','Private fields وmethods محددة وgetters/setters تساعد فرض قواعد تعديل البيانات.','خصوصية # ليست تشفيرًا لسر خدمة في المتصفح.',['Private field','Private Fields','private','التغليف']);
 add('this','سياق الاستدعاء','قيمة مرجعية في الدالة تتحدد حسب نوعها وطريقة استدعائها.','method عادية على object تقرأ this وفق الاستدعاء، وArrow تلتقط السياق المحيط.','مكان تعريف الدالة العادية وحده لا يثبت this إلى الأبد.');
 add('Git','تتبع نسخ الملفات','نظام يسجل تاريخ تغييرات المصدر ويسمح بمقارنة النسخ والفروع.','GitHub يستضيف المستودع ويسهّل التعاون، بينما Git الأداة التي تدير السجل.','تعديل ملف محلي لا يعني أنه اتنشر على GitHub أو Vercel تلقائيًا.',['GitHub']);
 add('Vercel','استضافة ونشر','خدمة تقدم نسخة الموقع وتنفذ إعدادات البناء والنشر المتصلة بالمشروع.','المستودع قد يكون مربوطًا بنشر تلقائي عند تحديث فرع معين حسب الإعدادات.','نجاح حفظ ملف محلي ليس نشرًا؛ يلزم تحديث المصدر المتصل والتحقق من نتيجة النشر.');

 add('Updater','دالة حساب الحالة التالية','دالة تمررها إلى setter وتستقبل ناتج الحالة السابق المناسب في طابور التحديث.','ترجع الحالة التالية فقط؛ React تمرر الناتج للمحدث التالي عند وجود عدة تحديثات.','خليها نقية، ولا تولد معرفًا عشوائيًا أو تبدأ طلبًا داخلها.',['updater','updater function']);
 add('Composition','تركيب المكونات','بناء جزء أكبر عن طريق جمع Components ومحتوى بدل نسخ منطقها أو تضخيم شروطها.','children وprops التي تحمل عناصر تسمح للحاوية بتحديد الإطار وللمستدعي بتحديد المحتوى.','مشاركة التركيب لا تعني مشاركة state تلقائيًا.',['composition']);
 add('Pure function','دالة نقية','دالة تحسب نتيجة من مدخلاتها بدون تغيير مدخلات موجودة أو تنفيذ أثر خارجي أثناء الحساب.','في render React قد تعيد الحساب، فالنقاء يجعل النتيجة قابلة للتوقع حتى مع التكرار.','تعديل متغير محلي جديد أثناء الحساب يختلف عن تعديل object مشتركة من props.',['Purity','purity','نقي','نقية']);
 add('Side effect','أثر جانبي','تفاعل مع شيء خارج حساب النتيجة مثل طلب شبكة أو مؤقت أو تعديل وثيقة.','قد يكون مكانه handler عندما سببه تفاعل، أو Effect عندما المطلوب مزامنة مرتبطة بالظهور والاعتمادات.','ليس كل أثر جانبي محتاج useEffect؛ السبب هو اللي يحدد مكانه.',['side effect']);
 add('Declarative UI','وصف واجهة حسب البيانات','أسلوب يحدد النتيجة المطلوبة للحالة الحالية بدل كتابة كل خطوة تعديل DOM يدويًا.','Component ترجع JSX من المدخلات والحالة، وReact تنظم تطبيق النتيجة.','لا يعني أن التطبيق بلا خطوات تنفيذ؛ هي مسؤولية موزعة بين وصفك وآلية React.',['Declarative']);
 add('Mount','تركيب المكون','بدء وجود هوية Component في شجرة العرض الحالية.','تُهيأ حالتها وتطبق واجهتها وتبدأ مزامناتها المناسبة. الإزالة تنهي وجودها في ذلك الموضع.','CSS مخفية لا تعني بالضرورة Unmount، وإعادة render لا تعني Mount جديدًا.',['Unmount','unmount']);
 add('Falsy','قيمة تتحول لمنطقي خاطئ','مثل false و0 والنص الفاضي وnull وundefined وNaN عند التحويل المنطقي.','تؤثر في if و&& و||، بينما ?? تركز على null وundefined فقط.','array فاضية وobject فاضي مش falsy.',['falsy','Truthiness','truthiness']);
 add('Truthy','قيمة تتحول لمنطقي صحيح','أي قيمة يتحول استخدامها كشرط إلى true ضمن قواعد اللغة.','نص غير فاضي، بما فيه "false" أو "0"، يعتبر truthy؛ وكذلك objects وarrays.','اسم محتوى النص لا يحدد قيمته المنطقية.',['truthy']);
 add('Loop','حلقة تكرار','تركيب يعيد تنفيذ مجموعة خطوات حسب شرط أو عناصر.','for وwhile وdo...while تختلف في مكان التهيئة والتحديث وتوقيت اختبار الشرط.','لازم مسار التنفيذ يقترب من نهاية مناسبة؛ حلقة لا تنتهي قد تمنع استجابة الواجهة.',['Loops','loop','for','while','do...while']);
 add('Index','فهرس الموضع','رقم موضع داخل array أو مجموعة، يبدأ غالبًا من صفر في JavaScript.','الطول مش آخر فهرس؛ آخر موضع لarray كثيفة طولها n هو n-1.','موضع العنصر قد يتغير بعد بحث أو حذف، لذلك ليس بديلًا تلقائيًا عن id ثابت.',['index']);
 add('Reference','مرجع وهوية','طريقة وصول متغير لقيمة كائنية بهويتها بدل نسخ كل محتواها عند الإسناد.','متغيران قد يشيرا لنفس object، والمقارنة الصارمة تختبر الهوية.','Spread ينسخ المستوى الأول، لكن nested objects قد تظل مشتركة.',['المرجع']);
 add('Error handling','معالجة الفشل','تحديد مسار واضح عند استثناء أو رفض Promise أو فشل طلب.','try/catch مع await أو catch على Promise تتيح عرض رسالة وحفظ حالة واجهة متسقة.','ابتلاع كل الأخطاء بدون تشخيص يخفي أخطاء الكود؛ ميّز الإلغاء المتوقع عن الفشل.');
 add('Cairo','خط العرض العربي','اسم عائلة الخط المستخدمة في الموقع لعرض النص العربي.','يطلبه المتصفح من خدمة الخطوط إذا توفرت الشبكة، ثم يرجع لبدائل محلية عند عدم توفره.','فشل الخط الخارجي لا يمنع قراءة المحتوى لأن الخطوط البديلة موجودة.');
 add('LTS','دعم طويل للإصدار','تصنيف لإصدارات تحصل على دعم لفترة محددة وفق سياسة المشروع.','اختيار Node LTS مدعوم يقلل الاعتماد على إصدار منتهي الدعم مع مراعاة متطلبات أداة البناء.','LTS لا تعني دعمًا للأبد؛ راجع الحالة الحالية ومتطلبات Vite.');
 add('CLI','واجهة أوامر برنامج','طريقة تشغيل قدرات برنامج عن طريق كتابة أمر وخيارات في Terminal.','اسم البرنامج يتبعه فعل أو خيارات، والنتائج ترجع كنص وحالة خروج.','Terminal هي الواجهة الحاوية، وCLI طريقة تعامل برنامج داخلها؛ مش كل أمر من npm نفسه.');
 add('GET','طلب قراءة HTTP','طريقة HTTP معتادة لطلب تمثيل مورد.','عند form تقليدية تُضم البيانات غالبًا للاستعلام في العنوان؛ fetch الافتراضي يستخدم GET ما لم تغيره.','لا تضع بيانات حساسة في عنوان لأنه قد يظهر في السجل وروابط المشاركة.');
 add('POST','طلب معالجة HTTP','طريقة لإرسال محتوى للخدمة لمعالجته حسب عقدها.','البيانات تكون في body وفق Content-Type وطريقة الإرسال.','POST ليست تشفيرًا ولا ضمان تحقق؛ HTTPS وتحقق الخادم مسؤوليات أخرى.');
 add('NodeList','مجموعة عقد','واجهة لمجموعة nodes مثل نتيجة querySelectorAll.','قد توفر forEach، لكن ليست array عادية بكل methods. نتيجة querySelectorAll ثابتة بالنسبة للحظة الاختيار.','غياب العناصر يعني مجموعة طولها صفر، مش null مثل querySelector.');
 add('HTMLCollection','مجموعة عناصر','واجهة مجموعة عناصر ترجعها بعض APIs مثل getElementsByClassName.','غالبًا حية؛ إضافة أو حذف عناصر قد يغير محتواها أثناء المرور.','لا تتعامل معها كعنصر واحد ولا تفترض أن طولها ثابت أثناء تعديل DOM.');
 add('Pending','قيد الانتظار','حالة Promise قبل استقرارها النهائي.','تنتقل إلى fulfilled بقيمة أو rejected بسبب، بينما كود واجهتك يدير loading المناسب.','pending لا تعني أن كل JavaScript متوقف؛ متابعة غير متزامنة تنتظر.',['pending']);
 add('Fulfilled','مكتملة بقيمة','حالة Promise استقرت بنتيجة نجاح.','then أو await تحصل على القيمة وفق سلسلة المعالجة.','Resolved ليست دائمًا مرادفًا حرفيًا؛ الوعد قد يتبع وعدًا آخر لم يستقر بعد.',['fulfilled','Resolved','resolved']);
 add('Rejected','مرفوضة بسبب','حالة Promise استقرت بفشل أو سبب رفض.','catch أو try/catch مع await يعالجها ويحدد رد الفعل المناسب.','غياب معالج مناسب قد يؤدي إلى Unhandled rejection.',['rejected']);
 add('min-width','حد العرض الأدنى','قيد يمنع الصندوق من الانكماش لأقل من حد معين ضمن التخطيط.','القيمة التلقائية في عناصر flex أو grid قد تعتمد على حجم المحتوى الأدنى؛ 0 تسمح بانكماش مناسب في حالات كثيرة.','وضع min-width كبير على الهاتف قد يسبب خروجًا حتى لو width نسبة.');
 add('max-width','حد العرض الأقصى','قيد يوقف اتساع الصندوق بعد حجم معين.','مع width:100% يمكن ملء العرض المتاح لحد هذا الحد؛ margin قد تحقق التوسيط بشكل منفصل.','لا تحدد الارتفاع ولا تصلح كل قيود المحتوى أو الحشو وحدها.');
 add('font-size','حجم الحروف','قياس الخط المستخدم لعرض النص وفق الوحدة والحساب.','يرتبط به ارتفاع سطر نسبي ووحدات em وrem حسب مرجعها.','مش هو ارتفاع السطر النهائي وحده؛ line-height ومقاييس الخط جزء من النتيجة.');
 add('line-height','ارتفاع صندوق السطر','المساحة الرأسية المخصصة لسطر نص.','رقم بلا وحدة مثل 2 يساوي ضعف حجم خط العنصر المحسوب، ويساعد الوراثة المرنة.','قيمة صغيرة جدًا قد تسبب تداخلًا حتى لو حجم الحروف مناسب.');
 add('white-space','سياسة الفراغات واللف','خاصية تحدد الاحتفاظ بالمسافات والأسطر وطريقة لفها.','normal تضغط فراغات معتادة، وpre تحتفظ بها، وpre-wrap تجمع الحفظ والالتفاف المناسب.','نص طويل بلا نقاط كسر قد يحتاج overflow-wrap أيضًا؛ لا تعالج كل لف بهذه الخاصية وحدها.');
 add('overflow-wrap','السماح بكسر النص الطويل','تحدد فرص كسر كلمات أو روابط طويلة عند الحاجة داخل الصندوق.','anywhere تسمح بكسر مناسب لتجنب تجاوز عرض ضيق.','لا تعوض عرضًا ثابتًا غير منطقي، واختبر أثرها على قراءة الروابط والكود.');
 add('hover','حالة وجود المؤشر','مطابقة :hover عندما يشير مؤشر مناسب للعنصر حسب الجهاز والمتصفح.','تستخدم لتلميح بصري أو transition عند تغير قيمة.','ليست طريقة تفاعل مضمونة على اللمس، وفر تركيزًا واضحًا للكيبورد.',['Hover']);
